# SPDX-License-Identifier: MIT
"""Generate the public changelog page from `agf/CHANGELOG.md` at build time.

`agf/CHANGELOG.md` stays the only authored copy. The page
`reference/changelog.md` is written into the docs tree on every build (it is
gitignored, like `reference/release-info.md`), so the published site always
shows the changelog of the commit it was built from and no second copy can drift.

The build fails if the source file is missing: a changelog page that silently
disappears from the site is the failure this hook exists to prevent (plan:
docs/plans/external-review-response-docs.md, item 1).
"""

from __future__ import annotations

import re
from pathlib import Path

from mkdocs.exceptions import PluginError

# agf/CHANGELOG.md links into the site as `docs/site/<path>`, relative to agf/.
# The generated page sits in reference/, so those targets become `../<path>`.
SITE_LINK_RE = re.compile(r"\]\(docs/site/")

NOTICE = (
    "<!-- Generated at build time from agf/CHANGELOG.md by "
    "agf/docs/build/hooks/changelog_page.py. Do not edit this file. -->\n\n"
)


def on_pre_build(config, **kwargs) -> None:
    # config file is agf/docs/build/mkdocs.yml, so the changelog is three levels up.
    dist_root = Path(config.config_file_path).resolve().parent.parent.parent
    source = dist_root / "CHANGELOG.md"
    if not source.is_file():
        raise PluginError(f"changelog_page: source file not found: {source}")

    target = Path(config.docs_dir).resolve() / "reference" / "changelog.md"
    target.parent.mkdir(parents=True, exist_ok=True)
    body = SITE_LINK_RE.sub("](../", source.read_text(encoding="utf-8"))
    target.write_text(NOTICE + body, encoding="utf-8")
